// Normalize & Validate
// Cleans every field into the standard lead record, flags problems,
// and builds the material for the idempotency key (hashed in the next node).
// Runs once per execution; Process Lead always receives one lead at a time.

const FREE_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'yahoo.com', 'yahoo.co.uk', 'ymail.com', 'rocketmail.com',
  'hotmail.com', 'outlook.com', 'live.com', 'msn.com', 'aol.com', 'icloud.com', 'me.com',
  'mac.com', 'proton.me', 'protonmail.com', 'gmx.com', 'gmx.net', 'mail.com', 'zoho.com',
  'yandex.com', 'comcast.net', 'verizon.net', 'att.net', 'sbcglobal.net',
]);

const STATES = {
  AL: 'Alabama', AK: 'Alaska', AZ: 'Arizona', AR: 'Arkansas', CA: 'California', CO: 'Colorado',
  CT: 'Connecticut', DE: 'Delaware', DC: 'District of Columbia', FL: 'Florida', GA: 'Georgia',
  HI: 'Hawaii', ID: 'Idaho', IL: 'Illinois', IN: 'Indiana', IA: 'Iowa', KS: 'Kansas',
  KY: 'Kentucky', LA: 'Louisiana', ME: 'Maine', MD: 'Maryland', MA: 'Massachusetts',
  MI: 'Michigan', MN: 'Minnesota', MS: 'Mississippi', MO: 'Missouri', MT: 'Montana',
  NE: 'Nebraska', NV: 'Nevada', NH: 'New Hampshire', NJ: 'New Jersey', NM: 'New Mexico',
  NY: 'New York', NC: 'North Carolina', ND: 'North Dakota', OH: 'Ohio', OK: 'Oklahoma',
  OR: 'Oregon', PA: 'Pennsylvania', RI: 'Rhode Island', SC: 'South Carolina', SD: 'South Dakota',
  TN: 'Tennessee', TX: 'Texas', UT: 'Utah', VT: 'Vermont', VA: 'Virginia', WA: 'Washington',
  WV: 'West Virginia', WI: 'Wisconsin', WY: 'Wyoming',
};
const STATE_BY_NAME = Object.fromEntries(Object.entries(STATES).map(([code, name]) => [name.toLowerCase(), code]));
Object.assign(STATE_BY_NAME, {
  calif: 'CA', cal: 'CA', mass: 'MA', penn: 'PA', penna: 'PA', fla: 'FL', tex: 'TX',
  wash: 'WA', 'washington dc': 'DC', 'washington d c': 'DC', 'n carolina': 'NC',
  's carolina': 'SC', 'n dakota': 'ND', 's dakota': 'SD', 'w virginia': 'WV',
});

const SOURCE_LABELS = { form: 'Web form', webhook: 'Webhook', sheet: 'Google Sheet' };

const clean = (v) => (v === null || v === undefined ? '' : String(v).replace(/\s+/g, ' ').trim());

// Capitalize names typed in all lower or all upper case; keep mixed case as typed (McDonald, DeShawn).
function nameCase(v) {
  const s = clean(v);
  if (!s) return '';
  if (s !== s.toLowerCase() && s !== s.toUpperCase()) return s;
  return s.toLowerCase().replace(/(^|[\s'-])([a-z])/g, (m, sep, ch) => sep + ch.toUpperCase());
}

function normEmail(v) {
  const s = clean(v).replace(/^mailto:/i, '').replace(/^<|>$/g, '').toLowerCase();
  const valid = /^[a-z0-9._%+'-]+@[a-z0-9-]+(\.[a-z0-9-]+)*\.[a-z]{2,}$/.test(s) && !s.includes('..');
  return { email: s, valid };
}

function normPhone(v, countryCode) {
  const raw = clean(v);
  if (!raw) return { phone: '', warning: '' };
  const main = raw.split(/\s*(?:ext\.?|extension|x|#)\s*\d+\s*$/i)[0];
  const hasPlus = main.trim().startsWith('+');
  const digits = main.replace(/\D/g, '');
  if (hasPlus && digits.length >= 8 && digits.length <= 15) return { phone: '+' + digits, warning: '' };
  const northAmerica = !countryCode || countryCode === 'US' || countryCode === 'Canada';
  if (northAmerica && digits.length === 10) return { phone: '+1' + digits, warning: '' };
  if (northAmerica && digits.length === 11 && digits.startsWith('1')) return { phone: '+' + digits, warning: '' };
  return { phone: '', warning: `Phone could not be converted to international format: ${raw}` };
}

function normState(v) {
  const s = clean(v).replace(/\./g, '').toLowerCase();
  if (!s) return { state: '', warning: '' };
  if (s.length === 2 && STATES[s.toUpperCase()]) return { state: s.toUpperCase(), warning: '' };
  const code = STATE_BY_NAME[s];
  return code ? { state: code, warning: '' } : { state: '', warning: `Unknown US state: ${clean(v)}` };
}

function normCountry(v, stateCode) {
  const s = clean(v).replace(/\./g, '').toLowerCase();
  if (!s) return stateCode ? 'US' : '';
  if (['us', 'usa', 'u s', 'u s a', 'united states', 'united states of america', 'america'].includes(s)) return 'US';
  if (['ca', 'can', 'canada'].includes(s)) return 'Canada';
  if (['uk', 'gb', 'united kingdom', 'great britain', 'england', 'scotland', 'wales'].includes(s)) return 'United Kingdom';
  return nameCase(clean(v));
}

// Turn "1,200", "35 employees", "11-50" or "1000+" into a standard band.
function sizeBand(v) {
  const s = clean(v).toLowerCase().replace(/,/g, '');
  if (!s) return '';
  const canonical = { '1-10': '1-10', '11-50': '11-50', '51-200': '51-200', '201-1000': '201-1000', '1000+': '1000+' };
  const compact = s.replace(/\s|employees?|people|staff/g, '');
  if (canonical[compact]) return canonical[compact];
  const nums = [...s.matchAll(/(\d+(?:\.\d+)?)\s*(k)?/g)].map((m) => parseFloat(m[1]) * (m[2] ? 1000 : 1));
  if (!nums.length) return '';
  const n = nums.length >= 2 ? (nums[0] + nums[1]) / 2 : nums[0];
  if (n <= 10) return '1-10';
  if (n <= 50) return '11-50';
  if (n <= 200) return '51-200';
  if (n <= 1000) return '201-1000';
  return '1000+';
}

// Turn "$20,000", "25k", "10000-20000" (midpoint) or "under 5k" into a standard budget band.
function budgetBand(v) {
  const s = clean(v).toLowerCase();
  if (!s) return { band: '', usd: null };
  const canonical = {
    'under$5k': 'Under $5k', '$5k-$15k': '$5k-$15k', '$15k-$50k': '$15k-$50k', '$50k+': '$50k+',
  };
  const key = s.replace(/\s+/g, '');
  if (canonical[key]) return { band: canonical[key], usd: null };
  if (/^(not sure( yet)?|unsure|unknown|tbd|n\/a|na|\?|don't know|dont know)$/.test(s)) return { band: 'Not sure', usd: null };
  const nums = [...s.replace(/[$,\s]/g, '').matchAll(/(\d+(?:\.\d+)?)(k|m)?/g)]
    .map((m) => parseFloat(m[1]) * (m[2] === 'k' ? 1e3 : m[2] === 'm' ? 1e6 : 1));
  if (!nums.length) return { band: '', usd: null };
  let usd = nums.length >= 2 ? (nums[0] + nums[1]) / 2 : nums[0];
  if (/under|less than|below|</.test(s)) usd -= 1;
  const band = usd < 5000 ? 'Under $5k' : usd < 15000 ? '$5k-$15k' : usd < 50000 ? '$15k-$50k' : '$50k+';
  return { band, usd: Math.round(usd) };
}

function timelineNorm(v) {
  const s = clean(v).toLowerCase();
  if (!s) return '';
  if (/asap|immediate|urgent|right away|this week|this month|^now$/.test(s)) return 'ASAP';
  if (/1\s*(-|to)\s*3|this quarter|next month|within 3 months|1-3/.test(s)) return '1-3 months';
  if (/3\s*(-|to)\s*6|next quarter|6 months|3-6/.test(s)) return '3-6 months';
  if (/research|exploring|just looking|not sure|no rush|next year|6\+|later/.test(s)) return 'Just researching';
  return clean(v);
}

function serviceNorm(v) {
  const s = clean(v).toLowerCase();
  if (!s) return '';
  if (/cyber|security|phishing|ransomware|compliance/.test(s)) return 'Cybersecurity';
  if (/microsoft 365|m365|office 365|o365/.test(s)) return 'Microsoft 365 Setup';
  if (/cloud|azure|aws|migration/.test(s)) return 'Cloud Migration';
  if (/managed|help ?desk|support|msp/.test(s)) return 'Managed IT Support';
  if (/consult|strategy|assessment|audit|advice/.test(s)) return 'IT Consulting';
  return 'Other';
}

// Text that looks like code. It is stored as plain text either way (every query is parameterized),
// but HubSpot's firewall answers 403 to records containing it, so such leads skip the CRM upsert.
const CODE_PATTERNS = [
  ['HTML', /<\/?[a-z][a-z0-9-]*(\s[^<>]*)?\/?>/i],
  ['HTML', /javascript\s*:/i],
  ['SQL', /\b(drop|truncate|alter)\s+table\b/i],
  ['SQL', /\bunion\s+(all\s+)?select\b/i],
  ['SQL', /'\s*(or|and)\s+'?\w+'?\s*=\s*'?\w+/i],
  ['SQL', /;\s*--/],
];
function looksLikeCode(values) {
  const kinds = new Set();
  for (const v of values) for (const [kind, re] of CODE_PATTERNS) if (re.test(String(v ?? ''))) kinds.add(kind);
  return [...kinds].join(' and ');
}

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
  });
}

return $input.all().map((item) => {
  const d = item.json;
  const source = clean(d.source).toLowerCase() || 'webhook';
  const warnings = [];
  const errors = [];

  let firstName = nameCase(d.first_name);
  let lastName = nameCase(d.last_name);
  if (!firstName && clean(d.name)) {
    const parts = nameCase(d.name).split(' ');
    firstName = parts.shift();
    lastName = lastName || parts.join(' ');
  }

  const { email, valid: emailValid } = normEmail(d.email);
  const emailDomain = emailValid ? email.split('@')[1] : '';
  const emailType = !emailValid ? '' : FREE_EMAIL_DOMAINS.has(emailDomain) ? 'free' : 'business';
  if (emailType === 'free') warnings.push(`Free email domain (${emailDomain})`);

  const stateResult = normState(d.state);
  const country = normCountry(d.country, stateResult.state);
  if (stateResult.warning && (country === 'US' || country === '')) warnings.push(stateResult.warning);
  const phoneResult = normPhone(d.phone, country);
  if (phoneResult.warning) warnings.push(phoneResult.warning);
  const budget = budgetBand(d.budget);
  const company = clean(d.company);
  const serviceInterest = serviceNorm(d.service_interest);

  const codeLike = looksLikeCode([firstName, lastName, company, d.job_title, d.message]);
  if (codeLike) warnings.push(`Looks like code (${codeLike}), kept out of HubSpot for review`);

  if (!firstName) errors.push('Missing first name');
  if (!email) errors.push('Missing email');
  else if (!emailValid) errors.push(`Invalid email format: ${clean(d.email)}`);
  if (!company) errors.push('Missing company');
  if (!serviceInterest) errors.push('Missing service interest');

  const lead = {
    lead_id: uuidv4(),
    received_at: new Date().toISOString(),
    source,
    source_label: SOURCE_LABELS[source] || source,
    source_event_id: clean(d.source_event_id),
    submitted_at: clean(d.submitted_at),
    first_name: firstName,
    last_name: lastName,
    full_name: [firstName, lastName].filter(Boolean).join(' '),
    email,
    email_domain: emailDomain,
    email_type: emailType,
    company,
    company_domain: emailType === 'business' ? emailDomain : '',
    job_title: clean(d.job_title),
    phone: phoneResult.phone,
    phone_input: clean(d.phone),
    state: stateResult.state,
    state_input: clean(d.state),
    country,
    company_size_band: sizeBand(d.company_size),
    company_size_input: clean(d.company_size),
    budget_band: budget.band,
    budget_usd: budget.usd,
    budget_input: clean(d.budget),
    service_interest: serviceInterest,
    timeline: timelineNorm(d.timeline),
    message: clean(d.message).slice(0, 2000),
    sheet_row_number: d.sheet_row_number ? Number(d.sheet_row_number) : null,
    validation_errors: errors,
    warnings,
    crm_hold: !!codeLike,
    is_valid: errors.length === 0,
  };

  // Idempotency material: the source's own event ID when it has one,
  // otherwise email + the source's submission timestamp, otherwise the content itself.
  // Never our receive time, so a retried delivery produces the same key.
  if (lead.source_event_id) {
    lead.idem_material = `${source}|event|${lead.source_event_id}`;
  } else if (lead.submitted_at && (email || company)) {
    lead.idem_material = `${source}|${email || company.toLowerCase()}|${lead.submitted_at}`;
  } else {
    const content = [email, lead.phone, company.toLowerCase(), firstName.toLowerCase(), lastName.toLowerCase(),
      lead.service_interest, lead.budget_band, lead.company_size_band, lead.timeline, lead.message];
    lead.idem_material = `${source}|content|${JSON.stringify(content)}`;
  }

  // Compact copy for the audit log (used by the duplicate and rejection paths).
  lead.log_details = {
    lead: {
      first_name: lead.first_name, last_name: lead.last_name, email: lead.email, email_type: lead.email_type,
      phone: lead.phone, phone_input: lead.phone_input, company: lead.company, job_title: lead.job_title,
      state: lead.state, country: lead.country, company_size_band: lead.company_size_band,
      budget_band: lead.budget_band, service_interest: lead.service_interest, timeline: lead.timeline,
      submitted_at: lead.submitted_at,
    },
    validation_errors: errors,
    warnings,
    sheet_row_number: lead.sheet_row_number,
    idem_material: lead.idem_material,
  };

  return { json: lead };
});

