// Parse Config Tabs
// "Read Config Tabs" fetches scoring_rules, territories and reps in ONE Sheets API call (values:batchGet).
// Google allows 60 reads per minute per service account, so one call per lead instead of three
// keeps a burst of leads under the limit. This node turns each tab into row objects keyed by its header row.

const ranges = $input.first().json.valueRanges || [];

function tab(name) {
  const found = ranges.find((r) => String(r.range || '').replace(/'/g, '').split('!')[0] === name);
  if (!found) throw new Error(`Could not read the "${name}" tab of the config sheet. Check that the tab exists and has not been renamed.`);
  const [header = [], ...rows] = found.values || [];
  const keys = header.map((h) => String(h ?? '').trim());
  return rows
    .filter((row) => row.some((v) => String(v ?? '').trim() !== ''))
    .map((row, i) => {
      const obj = { row_number: i + 2 };
      keys.forEach((k, j) => { if (k) obj[k] = row[j] ?? ''; });
      return obj;
    });
}

return [{ json: { scoring_rules: tab('scoring_rules'), territories: tab('territories'), reps: tab('reps') } }];

// Score & Choose Pool
// 1) Scores the lead with the rules from the scoring_rules tab.
// 2) Decides the route: returning contact, hot lead, territory, or manager fallback.
// 3) Lists the available reps who can take it; the next node picks one round-robin.

const cfg = $('Config').first().json.config;
const lead = $('Merge Claim Result').first().json;
const hubspot = $('Find Contact in HubSpot').first().json || {};
const previous = $('Find Previous Assignment').first().json || {};

const truthy = (v) => ['true', 'yes', 'y', '1', 'x'].includes(String(v ?? '').trim().toLowerCase());
const text = (v) => String(v ?? '').trim();
const lower = (v) => text(v).toLowerCase();
const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// ---------- 1. Scoring ----------
const tabs = $('Parse Config Tabs').first().json;
const rules = (tabs.scoring_rules || []).filter((r) => text(r.rule_id) && truthy(r.active));

function ruleMatches(rule, value) {
  const op = lower(rule.operator);
  const v = lower(value);
  const list = text(rule.value).split(',').map((x) => x.trim().toLowerCase()).filter(Boolean);
  switch (op) {
    case 'equals': return v !== '' && v === lower(rule.value);
    case 'not_equals': return v !== lower(rule.value);
    case 'in': return v !== '' && list.includes(v);
    case 'not_in': return !list.includes(v);
    case 'contains_any': return list.some((w) => new RegExp(`\\b${escapeRe(w)}\\b`, 'i').test(text(value)));
    case 'gte': return value !== '' && value !== null && Number(value) >= Number(rule.value);
    case 'lte': return value !== '' && value !== null && Number(value) <= Number(rule.value);
    case 'not_empty': return v !== '';
    case 'is_empty': return v === '';
    default: return false;
  }
}

let score = 0;
const breakdown = [];
for (const rule of rules) {
  if (ruleMatches(rule, lead[text(rule.field)])) {
    const points = Number(rule.points) || 0;
    score += points;
    breakdown.push({ rule_id: text(rule.rule_id), label: text(rule.label) || text(rule.rule_id), points });
  }
}
const hot = Number(cfg.hot_threshold);
const warm = Number(cfg.warm_threshold);
const priority = score >= hot ? 'Hot' : score >= warm ? 'Warm' : 'Cold';

// ---------- 2. Reps and territories ----------
const reps = (tabs.reps || []).filter((r) => text(r.rep_id)).map((r) => ({
  rep_id: text(r.rep_id),
  name: text(r.name),
  email: text(r.email),
  pool: lower(r.pool),
  available: truthy(r.available),
  slack_member_id: text(r.slack_member_id),
  hubspot_owner_id: text(r.hubspot_owner_id),
}));
const repDirectory = Object.fromEntries(reps.map((r) => [r.rep_id, r]));
const territories = Object.fromEntries(
  (tabs.territories || []).filter((t) => text(t.state_code))
    .map((t) => [text(t.state_code).toUpperCase(), lower(t.pool)]),
);
const availableIn = (pool) => reps.filter((r) => r.pool === pool && r.available).map((r) => r.rep_id);
const fallbackPool = lower(cfg.fallback_pool) || 'manager';

// ---------- 3. Routing decision ----------
const existingContact = (hubspot.results || [])[0] || null;
const props = existingContact?.properties || {};
const ownerMatch = reps.find((r) => r.hubspot_owner_id && r.hubspot_owner_id === text(props.hubspot_owner_id));
const existingRepId = text(previous.previous_rep_id) || text(props.lr_assigned_rep_id) || ownerMatch?.rep_id || '';

let routeType;
let pool;
let reason;
let candidates = [];
let assignedRepId = '';
const notes = [];

const existingRep = repDirectory[existingRepId];
if (existingRep && existingRep.available) {
  routeType = 'returning';
  pool = existingRep.pool;
  assignedRepId = existingRep.rep_id;
  reason = `Returning contact, kept with ${existingRep.name}`;
} else {
  if (existingRepId) notes.push(`previous rep ${existingRep ? existingRep.name : existingRepId} is unavailable`);
  if (score >= hot) {
    routeType = 'score';
    pool = 'enterprise';
    reason = `Hot lead (score ${score}), sent to the Enterprise pool`;
  } else if (lead.country === 'US' && territories[lead.state]) {
    routeType = 'territory';
    pool = territories[lead.state];
    reason = `Territory ${lead.state}, sent to the ${pool} pool`;
  } else {
    routeType = 'no_territory';
    pool = fallbackPool;
    reason = `No territory match (country: ${lead.country || 'blank'}, state: ${lead.state || 'blank'}), sent to the ${fallbackPool} pool`;
  }
  candidates = availableIn(pool);
  if (!candidates.length && pool !== fallbackPool) {
    notes.push(`no available reps in the ${pool} pool`);
    routeType = 'fallback';
    pool = fallbackPool;
    candidates = availableIn(fallbackPool);
  }
  if (!candidates.length) {
    routeType = 'unassigned';
    notes.push(`no available reps in the ${fallbackPool} pool either`);
  }
}
if (notes.length) reason += ` (${notes.join('; ')})`;

return [{
  json: {
    ...lead,
    score,
    score_breakdown: breakdown,
    score_summary: breakdown.map((b) => `${b.label} +${b.points}`).join(', ') || 'No scoring rules matched',
    priority,
    route_type: routeType,
    pool,
    routing_reason: reason,
    candidate_rep_ids: candidates,
    needs_rotation: candidates.length > 0 && routeType !== 'returning',
    assigned_rep_id: assignedRepId,
    existing_contact_id: existingContact ? text(existingContact.id) : '',
    rep_directory: repDirectory,
  },
}];

// Finalize Assignment
// Combines the routing decision with the rep picked by the round-robin query,
// then builds the HubSpot contact properties. Blank values are left out on purpose
// so a sparse resubmission can never wipe data already in the CRM.

const decision = $('Score & Choose Pool').first().json;
const input = $input.first().json || {};

let routeType = decision.route_type;
let reason = decision.routing_reason;
let repId = decision.assigned_rep_id;

if (decision.needs_rotation) {
  repId = String(input.picked_rep_id ?? '');
  if (!repId) {
    routeType = 'unassigned';
    reason += ' (round-robin found no rep to lock, left unassigned)';
  }
}

const rep = repId ? decision.rep_directory[repId] || null : null;
if (repId && !rep) {
  routeType = 'unassigned';
  reason += ` (rep ${repId} not found in the reps tab)`;
}

const hubspotProperties = {
  email: decision.email,
  firstname: decision.first_name,
  lastname: decision.last_name,
  phone: decision.phone || decision.phone_input,
  company: decision.company,
  jobtitle: decision.job_title,
  state: decision.state,
  country: decision.country,
  lr_lead_score: String(decision.score),
  lr_priority: decision.priority,
  lr_assigned_rep: rep ? rep.name : 'Unassigned',
  lr_assigned_rep_id: rep ? rep.rep_id : '',
  lr_routing_reason: reason,
  lr_source: decision.source_label,
  lr_service_interest: decision.service_interest,
  lr_company_size: decision.company_size_band,
  lr_budget: decision.budget_band,
  lr_timeline: decision.timeline,
  lr_last_message: decision.message,
  hubspot_owner_id: rep ? rep.hubspot_owner_id : '',
};
for (const [key, value] of Object.entries(hubspotProperties)) {
  if (value === null || value === undefined || String(value).trim() === '') delete hubspotProperties[key];
}

const { rep_directory, ...rest } = decision;

return [{
  json: {
    ...rest,
    route_type: routeType,
    routing_reason: reason,
    assigned_rep_id: rep ? rep.rep_id : '',
    assigned_rep: rep,
    event: rep ? 'routed' : 'unassigned',
    hubspot_properties: hubspotProperties,
  },
}];

// Build Notifications
// Reads the HubSpot upsert result, then prepares the Slack message, the hot-lead email
// and the audit log record. Keeping all wording here makes it easy to change in one place.

const cfg = $('Config').first().json.config;
const lead = $('Finalize Assignment').first().json;
const upsert = $input.first().json || {};
const contact = (upsert.results || [])[0] || {};

const crmContactId = String(contact.id ?? '');
const crmIsNew = contact.new === true;
const portalId = String(cfg.hubspot_portal_id ?? '').trim();
const crmUrl = crmContactId
  ? (portalId ? `https://app.hubspot.com/contacts/${portalId}/record/0-1/${crmContactId}` : String(contact.url ?? ''))
  : '';

const rep = lead.assigned_rep;
const icon = { Hot: ':fire:', Warm: ':large_orange_circle:', Cold: ':white_circle:' }[lead.priority] || ':bust_in_silhouette:';
const mention = rep ? (rep.slack_member_id ? `<@${rep.slack_member_id}>` : `*${rep.name}*`) : '*nobody (no rep available)*';
const titleLine = [lead.job_title, lead.company].filter(Boolean).join(' at ');
const sizeText = lead.company_size_band ? ` (${lead.company_size_band} employees)` : '';

const slackLines = [
  `${icon} *${lead.priority} lead* assigned to ${mention}${lead.route_type === 'returning' ? ' (returning contact)' : ''}`,
  `*${lead.full_name}*${titleLine ? `, ${titleLine}` : ''}${sizeText}`,
  `${lead.email}${lead.phone ? ` | ${lead.phone}` : ''}${lead.state ? ` | ${lead.state}` : lead.country ? ` | ${lead.country}` : ''}`,
  `*Service:* ${lead.service_interest || 'n/a'} | *Budget:* ${lead.budget_band || 'n/a'} | *Timeline:* ${lead.timeline || 'n/a'}`,
  `*Score:* ${lead.score} (${lead.score_summary})`,
  `*Routing:* ${lead.routing_reason}`,
  `*Source:* ${lead.source_label}${crmUrl ? ` | <${crmUrl}|Open in HubSpot>` : ''}`,
];
if (lead.message) slackLines.push(`> ${lead.message.slice(0, 300)}`);
if (!rep) slackLines.unshift(':rotating_light: *Unassigned lead, please assign it manually in HubSpot*');
if (lead.crm_hold) slackLines.push(':warning: *Not added to HubSpot:* this lead contains text that looks like code (HTML or SQL), which HubSpot blocks. Check it before adding it by hand.');

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const row = (k, v) => `<tr><td style="padding:4px 12px 4px 0;color:#555">${k}</td><td style="padding:4px 0">${esc(v) || 'n/a'}</td></tr>`;
const emailHtml = `
<p>Hi ${esc(rep ? rep.name.split(' ')[0] : 'team')},</p>
<p>A <strong>hot lead</strong> was just assigned to you. Please reach out today.</p>
<table style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:14px">
${row('Name', lead.full_name)}${row('Title', lead.job_title)}${row('Company', lead.company)}
${row('Email', lead.email)}${row('Phone', lead.phone || lead.phone_input)}${row('Location', [lead.state, lead.country].filter(Boolean).join(', '))}
${row('Company size', lead.company_size_band)}${row('Budget', lead.budget_band)}${row('Service', lead.service_interest)}
${row('Timeline', lead.timeline)}${row('Score', `${lead.score} (${lead.score_summary})`)}${row('Message', lead.message)}
</table>
${crmUrl ? `<p><a href="${crmUrl}">Open the contact in HubSpot</a></p>` : ''}
<p style="color:#888;font-size:12px">Sent by the lead router.</p>`;

const logRecord = {
  event: lead.event,
  lead_id: lead.lead_id,
  idem_key: lead.idem_key,
  source: lead.source,
  source_event_id: lead.source_event_id || null,
  email: lead.email,
  company: lead.company,
  score: lead.score,
  priority: lead.priority,
  pool: lead.pool,
  route_type: lead.route_type,
  rep_id: rep ? rep.rep_id : null,
  rep_name: rep ? rep.name : null,
  reason: lead.routing_reason,
  crm_contact_id: crmContactId || null,
  crm_is_new: crmContactId ? crmIsNew : null,
  details: {
    lead: {
      first_name: lead.first_name, last_name: lead.last_name, email: lead.email, email_type: lead.email_type,
      phone: lead.phone, phone_input: lead.phone_input, company: lead.company, job_title: lead.job_title,
      state: lead.state, country: lead.country, company_size_band: lead.company_size_band,
      budget_band: lead.budget_band, service_interest: lead.service_interest, timeline: lead.timeline,
      submitted_at: lead.submitted_at,
    },
    score_breakdown: lead.score_breakdown,
    warnings: lead.warnings,
    claim_attempts: lead.claim_attempts,
    crm_url: crmUrl,
    sheet_row_number: lead.sheet_row_number,
  },
  workflow_name: $workflow.name,
  execution_id: String($execution.id),
};

return [{
  json: {
    is_hot: lead.priority === 'Hot' && !!rep && !!rep.email,
    slack_channel: rep ? cfg.slack_leads_channel : cfg.slack_alerts_channel,
    slack_text: slackLines.join('\n'),
    email_to: rep ? rep.email : '',
    email_subject: `Hot lead: ${lead.full_name}, ${lead.company} (score ${lead.score})`,
    email_html: emailHtml,
    crm_contact_id: crmContactId,
    crm_is_new: crmIsNew,
    crm_url: crmUrl,
    log_record: logRecord,
  },
}];
